/**
 * Inline this in <head> before any stylesheet (or in the root layout) so the saved or system
 * theme is applied before first paint. Server-safe: this module has no client directive.
 */
export const NO_FLASH_SCRIPT = "(function(){try{var t=localStorage.getItem('theme');if(t!=='light'&&t!=='dark'){t=window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}document.documentElement.setAttribute('data-theme',t)}catch(e){}})();";

export type ColorToken = keyof typeof color;
export type SpaceToken = keyof typeof space;
export type TextRole = keyof typeof text;
